export function buildPcc1(){const A=ASSUMED265,S=A.side,root=new THREE.Group();root.name='Edificio_PCC1';const floors=[];
 FLOORS265.forEach((f,i)=>{const g=new THREE.Group();g.name='Piso_'+f.id;g.position.y=floorBase265(i);g.userData={index:i,id:f.id,base:floorBase265(i)};box(g,S,.35,S,i===0?'#4b5357':'#6b7377',0,-.35,0,'Losa_'+f.id);const h=floorHeight265(i);
  const walls=new THREE.Group();walls.name='Muros_'+f.id;for(const[w,d,x,z]of[[S,.25,0,-S/2],[S,.25,0,S/2],[.25,S,-S/2,0],[.25,S,S/2,0]])box(walls,w,h-.35,d,'#cfd8dc',x,0,z,null,{transparent:true,opacity:.16,depthWrite:false});g.add(walls);
  for(let k=0;k<7;k++)box(g,3.2,.3,1.1,'#e0483f',-S/2+2,k*(h/7),-S/2+3+k*1.1,'Escalera_'+f.id);
  const c=new THREE.Group();c.name='Equipo_'+f.id;CONTENT[f.id](c);g.add(c);g.userData.content=c;root.add(g);floors.push(g);});
 // Fachada: volumen oscuro con celosía vertical, azotea roja con domo blanco y pórtico de estructura blanca al frente.
 const shell=new THREE.Group();shell.name='Fachada';const top=floorBase265(7)+A.storey,H=top;
 for(const[w,d,x,z]of[[S+.6,.3,0,-S/2-.2],[.3,S+.6,-S/2-.2,0],[.3,S+.6,S/2+.2,0]])box(shell,w,H,d,'#2b2a2c',x,0,z,'Fachada_muro');
 for(const s of[-1,1])box(shell,S/2-5,H,.3,'#2b2a2c',s*(S/4+2.6),0,S/2+.2,'Fachada_frente');box(shell,10.4,H-9,.3,'#1d1c1e',0,9,S/2+.2,'Fachada_frente_alto');box(shell,10.4,9,.2,'#3a3f42',0,0,S/2+.1,'Acceso_principal');
 const fin=new THREE.InstancedMesh(new THREE.BoxGeometry(.18,H,.35),mat('#3b3a3d'),4*44),M=new THREE.Matrix4();let n=0;for(let k=0;k<44;k++){const t=-S/2+.5+k*(S-1)/43;for(const[x,z]of[[t,-S/2-.5],[t,S/2+.5],[-S/2-.5,t],[S/2+.5,t]]){if(z===S/2+.5&&Math.abs(x)<5.4)continue;M.makeTranslation(x,H/2,z);fin.setMatrixAt(n++,M);}}fin.count=n;fin.name='Celosia_vertical';shell.add(fin);
 box(shell,S+.6,.5,S+.6,'#a3262e',0,top,0,'Azotea_roja');box(shell,S*.45,1.2,S*.4,'#f2f2f0',0,top+.5,0,'Domo_blanco');
 const steel='#e9ecee',pz=S/2+4;for(const s of[-1,1]){for(const dx of[0,3])for(const dz of[0,3])box(shell,.35,H+1,.35,steel,s*(9.5+dx),0,pz+dz-1.5,'Portico_columna');for(let y=3;y<H;y+=3.4){box(shell,3.4,.25,.25,steel,s*11,y,pz-1.5,'Portico_travesano');box(shell,3.4,.25,.25,steel,s*11,y,pz+1.5,'Portico_travesano');const d=box(shell,4.6,.2,.2,steel,s*11,y-1.7,pz+1.5,'Portico_diagonal');d.rotation.z=s*.82;}}
 for(const y of[H-1,H-4.5])box(shell,26,.4,.4,steel,0,y,pz,'Portico_viga');for(let k=0;k<8;k++){const d=box(shell,4.4,.2,.2,steel,-10.5+k*3,H-3,pz,'Portico_celosia');d.rotation.z=k%2?.9:-.9;}
 box(shell,6,3,.25,'#16181a',0,H-10,S/2+.5,'Placa_PCC1');label(shell,'P.C.C. 1 · Buen Tono',0,H-8.5,S/2+1.2,1.6);root.add(shell);
 box(root,S*2.4,.2,S*2.4,'#59636a',0,-.22,0,'Terreno').userData.ground=true;
 root.userData={floors,shell};return root;}

export function buildPcc2(){const root=new THREE.Group();root.name='Edificio_PCC2';const shell=new THREE.Group();shell.name='Fachada';box(shell,30,16,24,'#9aa7ad',0,0,0,'Volumen_no_descrito',{transparent:true,opacity:.14,depthWrite:false});label(shell,'P.C.C. 2 · edificio no descrito en el material',0,17.5,0,2);root.add(shell);
 const g=new THREE.Group();g.name='Piso_alumbrado_y_fuerza';g.userData={index:0,id:'sef',base:0};box(g,30,.3,24,'#6b7377',0,-.3,0,'Losa');const c=new THREE.Group();c.name='Equipo_sef';
 for(const[s,cto]of[[-1,'AA 109'],[1,'AB 109']]){const x=s*7;box(c,.3,.3,9,'#d8a13a',x-3.4,.3,7.5,`Cable_15kV_${cto.replace(' ','_')}`);label(c,`De P.C.C. 1 · circuito ${cto}`,x-3.4,2.2,11,.8);box(c,2,2.4,1.6,'#4d5d66',x-3.4,0,2,'Proteccion_transformador');box(c,2.6,2.2,2,'#5c6b73',x,0,2,'Transformador_500kVA');label(c,'Transformador de 500 kVA',x,3.4,2,.8);box(c,2,2.4,1.6,'#4d5d66',x+3.2,0,2,'Interruptor_baja_tension');box(c,3.4,2.2,1,'#3d5a80',x,0,-4,'Cabina_N');label(c,'Cabina «N»',x,3.2,-4,.6);}
 box(c,4,2.2,1,'#7b6aa8',0,0,-9,'Cabina_P');label(c,'Cabina «P»',0,3.2,-9,.6);g.add(c);g.userData.content=c;root.add(g);box(root,70,.2,60,'#59636a',0,-.42,0,'Terreno');root.userData={floors:[g],shell};return root;}

// --- Vista ---
const doc=typeof document!=='undefined'?document:null;let dialog,view;
class PccView265{
 constructor(dlg){this.dialog=dlg;this.canvas=dlg.querySelector('canvas');this.building=null;this.floor=null;this.buildT=null;}
 async init(){const {OrbitControls}=await import('./vendor/OrbitControls.js');this.renderer=new THREE.WebGLRenderer({canvas:this.canvas,antialias:true,powerPreference:'high-performance'});this.renderer.setPixelRatio(Math.min(1.5,window.devicePixelRatio||1));this.scene=new THREE.Scene();this.scene.background=new THREE.Color('#8fa3ae');this.scene.add(new THREE.HemisphereLight('#ffffff','#5a646a',1.5));const sun=new THREE.DirectionalLight('#fff4e0',2.2);sun.position.set(40,80,60);this.scene.add(sun);
  this.camera=new THREE.PerspectiveCamera(42,1,.5,900);this.controls=new OrbitControls(this.camera,this.canvas);this.controls.enableDamping=true;this.controls.maxPolarAngle=Math.PI*.495;this.controls.minDistance=8;this.controls.maxDistance=260;this.clock=new THREE.Clock();this.resize=()=>{const r=this.canvas.parentElement.getBoundingClientRect();if(r.width<2)return;this.renderer.setSize(r.width,r.height,false);this.camera.aspect=r.width/r.height;this.camera.updateProjectionMatrix();};window.addEventListener('resize',this.resize);}
 load(id){if(this.root){this.scene.remove(this.root);}this.id=id;this.root=id==='pcc1'?buildPcc1():buildPcc2();this.scene.add(this.root);this.floor=null;this.buildT=null;this.apply();this.frame(id==='pcc1'?[70,48,92]:[38,24,46],id==='pcc1'?[0,14,0]:[0,5,0]);}
 frame(pos,target){this.camera.position.set(...pos);this.controls.target.set(...target);this.controls.update();}
 // floor: null = edificio completo; -1 = corte con todos los pisos; n = un piso.
 show(mode){this.buildT=null;this.floor=mode;this.apply();const fl=this.root.userData.floors;if(mode==null)this.frame(this.id==='pcc1'?[70,48,92]:[38,24,46],this.id==='pcc1'?[0,14,0]:[0,5,0]);else if(mode===-1)this.frame([78,50,84],[0,12,0]);else{const y=fl[mode].userData.base;this.frame([30,y+30,42],[0,y+1,0]);}}
 apply(){const {floors,shell}=this.root.userData,m=this.floor;shell.visible=m==null;for(const f of floors){const i=f.userData.index;f.position.y=f.userData.base;f.visible=m==null?false:m===-1?true:i===m;f.userData.content.visible=true;f.traverse(o=>{if(o.isSprite)o.visible=m!==-1;});}if(this.id==='pcc2'){floors[0].visible=true;shell.visible=true;}const ground=this.root.getObjectByName('Terreno');if(ground)ground.visible=!(this.id==='pcc1'&&m===0);}
 build(){const {floors,shell}=this.root.userData;this.floor='build';this.buildT=0;shell.visible=false;for(const f of floors){f.visible=false;f.userData.content.visible=true;f.traverse(o=>{if(o.isSprite)o.visible=false;});}this.frame([84,56,96],[0,12,0]);}
 tick=()=>{if(!this.running)return;requestAnimationFrame(this.tick);const dt=Math.min(.05,this.clock.getDelta());if(this.buildT!=null){this.buildT+=dt;const {floors,shell}=this.root.userData,step=1.1;floors.forEach((f,i)=>{const t=(this.buildT-i*step)/step;f.visible=t>0;const e=Math.min(1,Math.max(0,t)),k=1-(1-e)**3;f.position.y=f.userData.base+(1-k)*26;});const done=this.buildT>floors.length*step;shell.visible=done&&this.buildT>floors.length*step+.6;this.onBuild?.(Math.min(floors.length,Math.floor(this.buildT/step)+1),shell.visible);if(shell.visible&&this.buildT>floors.length*step+2.4){this.buildT=null;this.floor=null;this.apply();}}this.controls.update();this.renderer.render(this.scene,this.camera);}
 start(){this.running=true;this.resize();this.clock.getDelta();requestAnimationFrame(this.tick);}stop(){this.running=false;}}

function html(){return `<div class="pcc265-header"><div><small>INFRAESTRUCTURA · EDIFICIOS DE MANDO</small><h2 id="pcc265-heading">Puestos Centrales de Control</h2></div><button type="button" data-pcc265-close>Volver ×</button></div>
<div class="pcc265-pick" data-pcc265-pick><p>Elige el edificio que quieres recorrer.</p><div>${BUILDINGS265.map(b=>`<button type="button" data-pcc265-building="${b.id}"><b>${b.name}</b><em>${b.place}</em><span>${b.lines}</span><small>${b.text}</small></button>`).join('')}</div></div>
<div class="pcc265-layout" data-pcc265-layout hidden><section class="pcc265-viewport"><canvas></canvas><div class="pcc265-tools"><button type="button" data-pcc265-back>← Elegir edificio</button><button type="button" data-pcc265-mode="shell" aria-pressed="true">Edificio completo</button><button type="button" data-pcc265-mode="cut">Corte por pisos</button><button type="button" data-pcc265-mode="build">Ver el armado</button></div><p class="pcc265-hint">Arrastra para girar · rueda para acercar · clic derecho para desplazar</p></section>
<aside class="pcc265-side"><h3 data-pcc265-name></h3><p data-pcc265-about></p><div data-pcc265-info></div><div class="pcc265-floors" data-pcc265-floors></div><p class="pcc265-note">${ASSUMED265.note}</p><p class="pcc265-note">Fuente: ${SOURCE265}</p></aside></div>`;}
function make(){dialog=doc.createElement('dialog');dialog.id='pcc265-dialog';dialog.setAttribute('aria-labelledby','pcc265-heading');dialog.innerHTML=html();doc.body.append(dialog);const q=s=>dialog.querySelector(s),pick=q('[data-pcc265-pick]'),layout=q('[data-pcc265-layout]'),info=q('[data-pcc265-info]'),floorsEl=q('[data-pcc265-floors]');
 const press=m=>dialog.querySelectorAll('[data-pcc265-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.pcc265Mode===m)));
 const pressFloor=i=>floorsEl.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.pcc265Floor)===i)));
 const showFloor=i=>{const f=FLOORS265[i];view.show(i);press('');pressFloor(i);info.innerHTML=`<h4>${f.name}</h4><p class="pcc265-slide">En la diapositiva: ${f.slide}</p><ul>${f.items.map(x=>`<li>${x}</li>`).join('')}</ul><p>${f.text}</p>`;};
 q('[data-pcc265-close]').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>view?.stop());
 q('[data-pcc265-back]').addEventListener('click',()=>{view.stop();layout.hidden=true;pick.hidden=false;});
 pick.addEventListener('click',async e=>{const b=e.target.closest('[data-pcc265-building]');if(!b)return;const B=BUILDINGS265.find(x=>x.id===b.dataset.pcc265Building);pick.hidden=true;layout.hidden=false;if(!view){view=new PccView265(dialog);await view.init();if(globalThis.location?.search?.includes('depurar225'))globalThis.pccView265=view;}
  view.onBuild=(n,shell)=>{info.innerHTML=`<h4>Armado del edificio</h4><p>${shell?'Se coloca la fachada: celosía oscura, azotea roja y pórtico de estructura blanca.':`Se coloca: ${FLOORS265[Math.min(n,FLOORS265.length)-1].name}.`}</p>`;};
  view.load(B.id);view.start();q('[data-pcc265-name]').textContent=`${B.name} · ${B.place}`;q('[data-pcc265-about]').textContent=`${B.lines}. ${B.text}`;press('shell');info.innerHTML='';const one=B.id==='pcc1';dialog.querySelectorAll('[data-pcc265-mode="cut"],[data-pcc265-mode="build"]').forEach(x=>x.hidden=!one);
  floorsEl.innerHTML=one?[...FLOORS265].map((f,i)=>[f,i]).reverse().map(([f,i])=>`<button type="button" data-pcc265-floor="${i}" aria-pressed="false"><b>${f.name}</b><span>${f.slide}</span></button>`).join(''):'<p>Subestación de alumbrado y fuerza: dos transformadores de 500 kVA, dos cabinas «N» y una cabina «P».</p>';});
 floorsEl.addEventListener('click',e=>{const b=e.target.closest('[data-pcc265-floor]');if(b)showFloor(Number(b.dataset.pcc265Floor));});
 dialog.addEventListener('click',e=>{const b=e.target.closest('[data-pcc265-mode]');if(!b||!view)return;const m=b.dataset.pcc265Mode;press(m);pressFloor(-9);info.innerHTML=m==='cut'?'<h4>Corte por pisos</h4><p>Sótano, planta baja y seis pisos. Elige un piso en la lista para ver su equipo.</p>':'';if(m==='shell')view.show(null);else if(m==='cut')view.show(-1);else view.build();});}
export async function open(){if(!doc)return;if(!dialog)make();if(dialog.open)return;dialog.querySelector('[data-pcc265-pick]').hidden=false;dialog.querySelector('[data-pcc265-layout]').hidden=true;dialog.showModal();}
if(typeof window!=='undefined')window.metroPcc265={open};
